package git

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

// gitCmd creates a git command with LC_ALL=C to ensure English output for parsing.
func gitCmd(args ...string) *exec.Cmd {
	cmd := exec.Command("git", args...)
	cmd.Env = append(os.Environ(), "LC_ALL=C")
	return cmd
}

// Run executes a git command and returns its trimmed stdout.
// If the command fails, the error includes stderr.
func Run(args ...string) (string, error) {
	return RunIn("", args...)
}

// RunIn executes a git command in a specific directory.
func RunIn(dir string, args ...string) (string, error) {
	cmd := gitCmd(args...)
	if dir != "" {
		cmd.Dir = dir
	}

	var stdout, stderr bytes.Buffer
	cmd.Stdout = &stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		errMsg := strings.TrimSpace(stderr.String())
		if errMsg == "" {
			errMsg = err.Error()
		}
		return "", fmt.Errorf("git %s: %s", strings.Join(args, " "), errMsg)
	}

	return strings.TrimSpace(stdout.String()), nil
}

// RunPassthrough executes a git command with stdout/stderr connected to the terminal.
// Used for commands where the user needs to see real-time output (rebase, push, etc.).
func RunPassthrough(args ...string) error {
	return RunPassthroughIn("", args...)
}

// RunPassthroughIn executes a git command in a directory with passthrough I/O.
func RunPassthroughIn(dir string, args ...string) error {
	cmd := gitCmd(args...)
	if dir != "" {
		cmd.Dir = dir
	}
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// RunSilent executes a git command and discards all output.
// Returns only whether it succeeded.
func RunSilent(args ...string) error {
	cmd := gitCmd(args...)
	cmd.Stdout = nil
	cmd.Stderr = nil
	return cmd.Run()
}

// RunSilentIn executes a git command in a directory silently.
func RunSilentIn(dir string, args ...string) error {
	cmd := gitCmd(args...)
	if dir != "" {
		cmd.Dir = dir
	}
	cmd.Stdout = nil
	cmd.Stderr = nil
	return cmd.Run()
}
package git

import (
	"strconv"
	"strings"
)

// FileChange represents a single file change from git status --porcelain.
type FileChange struct {
	Status string // Two-character status (e.g., "M ", " M", "??", "R ")
	Path   string
	// For renames: original path
	OldPath string
}

// IsRename returns true if this change is a rename.
func (f FileChange) IsRename() bool {
	return strings.HasPrefix(f.Status, "R")
}

// HasChanges returns true if the working tree has uncommitted changes.
func HasChanges() bool {
	out, err := Run("status", "--porcelain")
	if err != nil {
		return false
	}
	return strings.TrimSpace(out) != ""
}

// HasChangesIn returns true if a specific worktree has uncommitted changes.
func HasChangesIn(dir string) bool {
	out, err := RunIn(dir, "status", "--porcelain")
	if err != nil {
		return false
	}
	return strings.TrimSpace(out) != ""
}

// StatusShort returns the short status output for display.
func StatusShort() (string, error) {
	return Run("status", "--short")
}

// StatusPorcelain returns parsed file changes.
func StatusPorcelain() ([]FileChange, error) {
	return StatusPorcelainIn("")
}

// StatusPorcelainIn returns parsed file changes for a specific directory.
// Uses -uall to list individual files inside untracked directories,
// rather than collapsing them into a single directory entry.
func StatusPorcelainIn(dir string) ([]FileChange, error) {
	out, err := RunIn(dir, "status", "--porcelain", "-uall")
	if err != nil {
		return nil, err
	}
	return ParsePorcelainOutput(out), nil
}

// ParsePorcelainOutput parses the output of `git status --porcelain` into FileChanges.
func ParsePorcelainOutput(out string) []FileChange {
	if strings.TrimSpace(out) == "" {
		return nil
	}

	var changes []FileChange
	for line := range strings.SplitSeq(out, "\n") {
		if len(line) < 3 {
			continue
		}
		status := line[:2]
		path := line[3:]

		fc := FileChange{Status: status}

		// Handle renames: "R  old -> new"
		if strings.HasPrefix(status, "R") && strings.Contains(path, " -> ") {
			parts := strings.SplitN(path, " -> ", 2)
			fc.OldPath = parts[0]
			fc.Path = parts[1]
		} else {
			fc.Path = path
		}

		changes = append(changes, fc)
	}

	return changes
}

// UnpushedCountIn returns the number of commits ahead of the upstream.
func UnpushedCountIn(dir string) int {
	out, err := RunIn(dir, "rev-list", "--count", "@{upstream}..HEAD")
	if err != nil {
		return 0
	}
	n, _ := strconv.Atoi(strings.TrimSpace(out))
	return n
}
package git

import (
	"os"
	"path/filepath"
	"strings"
)

// Rebase runs `git rebase <onto>` with passthrough output.
func Rebase(onto string) error {
	return RunPassthrough("rebase", onto)
}

// RebaseIn runs rebase in a specific directory silently. Returns error on conflict.
func RebaseIn(dir, onto string) error {
	return RunSilentIn(dir, "rebase", onto)
}

// RebaseContinue continues an in-progress rebase.
func RebaseContinue() error {
	return RunPassthrough("rebase", "--continue")
}

// RebaseAbort aborts an in-progress rebase.
func RebaseAbort() error {
	return RunPassthrough("rebase", "--abort")
}

// RebaseAbortIn aborts a rebase in a specific directory.
func RebaseAbortIn(dir string) {
	_ = RunSilentIn(dir, "rebase", "--abort")
}

// IsRebaseInProgress checks if a rebase is currently active.
func IsRebaseInProgress() (bool, error) {
	gitDir, err := GitDir()
	if err != nil {
		return false, err
	}
	return isDir(filepath.Join(gitDir, "rebase-merge")) || isDir(filepath.Join(gitDir, "rebase-apply")), nil
}

// MergeFF does a fast-forward merge.
func MergeFF(ref string) (string, error) {
	return Run("merge", "--ff-only", ref)
}

// MergeFFIn does a fast-forward merge in a specific directory.
func MergeFFIn(dir, ref string) error {
	return RunSilentIn(dir, "merge", "--ff-only", ref)
}

// Push pushes with force-with-lease.
func PushForceWithLease() error {
	return RunPassthrough("push", "--force-with-lease")
}

// PushSetUpstream pushes and sets the upstream.
func PushSetUpstream(remote string) error {
	return RunPassthrough("push", "-u", remote, "HEAD")
}

// FetchPrune fetches and prunes dead remote refs.
func FetchPrune() {
	_ = RunSilent("fetch", "--prune")
}

// SaveStateFile writes the rebase state to a file in the git dir.
func SaveStateFile(name, content string) error {
	gitDir, err := GitDir()
	if err != nil {
		return err
	}
	return os.WriteFile(filepath.Join(gitDir, name), []byte(content), 0600)
}

// ReadStateFile reads a state file from the git dir.
func ReadStateFile(name string) (string, error) {
	gitDir, err := GitDir()
	if err != nil {
		return "", err
	}
	data, err := os.ReadFile(filepath.Join(gitDir, name))
	if err != nil {
		return "", err
	}
	return string(data), nil
}

// RemoveStateFile deletes a state file. Errors are ignored since
// leftover state files in .git/ are harmless.
func RemoveStateFile(name string) {
	gitDir, err := GitDir()
	if err != nil {
		return
	}
	_ = os.Remove(filepath.Join(gitDir, name))
}

// PotentialConflicts returns files modified on both HEAD and baseRef since they diverged.
// These files could potentially conflict during a rebase.
func PotentialConflicts(baseRef string) ([]string, error) {
	// Files changed on the base branch since divergence
	baseOut, err := Run("diff", "--name-only", "HEAD..."+baseRef)
	if err != nil {
		return nil, err
	}
	// Files changed on our branch since divergence
	oursOut, err := Run("diff", "--name-only", baseRef+"...HEAD")
	if err != nil {
		return nil, err
	}

	baseFiles := toSet(baseOut)
	var conflicts []string
	for line := range strings.SplitSeq(oursOut, "\n") {
		f := strings.TrimSpace(line)
		if f != "" && baseFiles[f] {
			conflicts = append(conflicts, f)
		}
	}
	return conflicts, nil
}

// toSet splits newline-delimited output into a set of non-empty strings.
func toSet(s string) map[string]bool {
	m := make(map[string]bool)
	for line := range strings.SplitSeq(s, "\n") {
		f := strings.TrimSpace(line)
		if f != "" {
			m[f] = true
		}
	}
	return m
}

// StateFileExists checks if a state file exists.
func StateFileExists(name string) bool {
	gitDir, err := GitDir()
	if err != nil {
		return false
	}
	return fileExists(filepath.Join(gitDir, name))
}

// DiffNameOnly returns filenames that changed between two refs.
func DiffNameOnly(ref1, ref2 string) ([]string, error) {
	return DiffNameOnlyIn("", ref1, ref2)
}

// DiffNameOnlyIn returns filenames that changed between two refs in a directory.
func DiffNameOnlyIn(dir, ref1, ref2 string) ([]string, error) {
	out, err := RunIn(dir, "diff", "--name-only", ref1, ref2)
	if err != nil {
		return nil, err
	}
	var files []string
	for line := range strings.SplitSeq(out, "\n") {
		f := strings.TrimSpace(line)
		if f != "" {
			files = append(files, f)
		}
	}
	return files, nil
}

// RevParseHead returns the current HEAD commit hash.
func RevParseHead() (string, error) {
	return Run("rev-parse", "HEAD")
}

// RevParseHeadIn returns the HEAD commit hash in a specific directory.
func RevParseHeadIn(dir string) (string, error) {
	return RunIn(dir, "rev-parse", "HEAD")
}

