	spin := ui.NewSpinner(fmt.Sprintf("Fetching %s", ctx.baseRef()))
	if err := git.Fetch(ctx.Config.Remote, ctx.Config.BaseBranch); err != nil {
		spin.Stop()
		restoreStash(didStash)
		git.RemoveStateFile(stateFileName)
